INSERT INTO tbdh_rows VALUES
(E'TH', E'TIENG_VIET', 10, E'1', E'Tranh ảnh › Chủ đề 1: Tập viết', NULL, E'Bộ mẫu chữ viết', E'Giúp học sinh thực hành quan sát, ghi nhớ mẫu chữ viết để viết cho đúng, đẹp.', E'a) Bộ mẫu chữ viết quy định trong trường tiểu học được phóng to, in 2 màu. Gồm 8 tờ, kích thước (540x790)mm, dung sai 10mm, in trên giấy couche, định lượng 200g/m2, cán láng OPP mờ, trong đó:\n- 4 tờ in bảng chữ cái viết thường, dấu thanh và chữ số;\n- 4 tờ in bảng chữ cái viết hoa.\nb) Mẫu chữ cái viết thường và chữ cái viết hoa đều được thể hiện ở 4 dạng: Chữ viết đứng, nét đều; chữ viết đứng, nét thanh, nét đậm; chữ viết nghiêng (15°), nét đều; chữ viết nghiêng, nét thanh, nét đậm.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'01/lớp', 1, E'PER_CLASS', NULL, E'1,2', E'Dùng cho lớp 1, 2', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'TH-TV-001', E'DM-TH-TV-001', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TIENG_VIET', 20, E'2', E'Tranh ảnh › Chủ đề 1: Tập viết', NULL, E'Bộ chữ dạy tập viết', E'Giúp học sinh thực hành quan sát mẫu chữ để hình thành biểu tượng về chữ cái, nhận biết các nét cơ bản và quy trình viết một chữ cái trước khi thực hành luyện tập bằng nhiều hình thức khác nhau.', E'Bộ mẫu chữ viết quy định trong trường tiểu học được phóng to, in 2 màu. Gồm 39 tờ, kích thước (210x290)mm, dung sai 10mm, in từng chữ cái, chữ số trên giấy couche, định lượng 200g/m2, cán láng OPP mờ. Trong đó:\n- 29 tờ in các chữ cái tiếng Việt (một mặt in chữ cái viết thường, một mặt in chữ cái viết hoa kiểu 1);\n- 5 tờ in chữ số kiểu 1 (gồm 10 chữ số từ 0 đến 9, in ở hai mặt);\n- 5 tờ một mặt in chữ cái viết hoa kiểu 2, một mặt in chữ số kiểu 2.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'1,2', E'Dùng cho lớp 1, 2', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'TH-TV-002', E'DM-TH-TV-002', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TIENG_VIET', 30, E'1', E'Tranh ảnh › Chủ đề 2: Học vần', NULL, E'Bộ thẻ chữ học vần thực hành', E'Giúp học sinh thực hành ghép vần, ghép tiếng, từ khoá, từ ngữ ứng dụng và thực hành vận dụng sáng tạo (ghép tiếng, từ mở rộng).', E'Bộ mẫu chữ viết quy định trong trường tiểu học được phóng to, in 2 màu. Bao gồm:\n- 80 thẻ chữ, kích thước (20x60)mm, in 29 chữ cái tiếng Việt (Font chữ Vnavant, cỡ 72, kiểu chữ đậm), in màu trên nhựa, gỗ (hoặc vật liệu có độ cứng tương đương), không cong vênh, chịu được nước, có màu tươi sáng, an toàn trong sử dụng; trong đó: d, đ, k, p, q, r, s, v, x, y (mỗi chữ cái có 2 thẻ); a, ă, â, b, c, e, ê, g, i, l, n, o, ô, ơ, u, ư (mỗi chữ cái có 3 thẻ); h, m, t (mỗi chữ cái có 4 thẻ);\n- 12 thẻ dấu ghi thanh, in màu trên mảnh nhựa trong, dùng để cài lên thẻ chữ; trong đó: hỏi, ngã, nặng (mỗi dấu có 2 mảnh), huyền, sắc (mỗi dấu có 3 mảnh).\n(Ghi chú: Các thẻ chữ có thể sử dụng với thanh cài hoặc bảng cá nhân có từ tính. Bảng cá nhân học sinh có 2 mặt, một mặt có thể viết phấn, một mặt có từ tính và viết được bút dạ.)', FALSE, TRUE, FALSE, E'BO', E'Bộ', E'01/HS', 1, E'PER_STUDENT', NULL, E'1', E'Dùng cho lớp 1', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'TH-TV-003', E'DM-TH-TV-003', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TIENG_VIET', 40, E'2', E'Tranh ảnh › Chủ đề 2: Học vần', NULL, E'Bộ chữ học vần biểu diễn', E'Hướng dẫn quá trình học tập âm vần mới bằng trực quan sinh động, hấp dẫn.', E'Bộ mẫu chữ viết quy định trong trường tiểu học. Bao gồm:\n- 97 thẻ chữ, kích thước (60x90)mm, in 29 chữ cái tiếng Việt (Font chữ Vnavant, cỡ 150), in đậm trên giấy couche, định lượng 200g/m2, cán láng OPP mờ: b, d, đ, e, l, ơ, r, s, v, x (mỗi chữ cái có 2 thẻ); ă, â, q (mỗi chữ cái có 3 thẻ); a, c, ê, g, i, k, m, o, ô, p, u, ư, y (mỗi chữ cái có 4 thẻ); n, t (mỗi chữ cái có 5 thẻ); h (6 thẻ);\n- Dấu ghi thanh (huyền, sắc, hỏi, ngã, nặng); dấu câu (dấu chấm, dấu phẩy, dấu chấm hỏi); in trên mảnh nhựa trong để cài lên thẻ chữ; mỗi dấu có 2 mảnh;\n- Các thẻ được in 2 mặt (chữ màu đỏ), một mặt in chữ cái thường, mặt sau in chữ cái hoa tương ứng;\n- Bảng phụ có 6 thanh nẹp để gắn chữ (6 dòng), kích thước (1.000x900)mm (hoặc bảng có từ tính để gắn thẻ chữ có nam châm).', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'1', E'Dùng cho lớp 1', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'TH-TV-004', E'DM-TH-TV-004', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TIENG_VIET', 50, E'1', E'Tranh ảnh › Chủ đề 3: Chính tả', E'Tên chữ cái tiếng Việt', E'Bảng tên chữ cái tiếng Việt', E'Giúp học sinh thuộc tên chữ cái tiếng Việt.', E'Bảng ghi tên chữ cái tiếng Việt in 2 màu, 1 tờ kích thước (540x790)mm, dung sai 10mm, in trên giấy couche, định lượng 200g/m2, cán láng OPP mờ.\nThiết kế 3 cột như sau:', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'02/lớp', 2, E'PER_CLASS', NULL, E'2,3', E'Dùng cho lớp 2, 3', E'TRANH_ANH_BAN_DO', E'PHYSICAL', E'SERIAL', NULL, E'TH-TV-005', E'DM-TH-TV-005', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TIENG_VIET', 60, E'1', E'Video/ clip › Chủ đề 1. Tập viết', NULL, E'Video dạy viết các chữ viết thường cỡ nhỡ theo bảng chữ cái tiếng Việt (2 kiểu: chữ đứng, chữ nghiêng)', E'Giúp học sinh thực hành quan sát, ghi nhớ mẫu các nét chữ viết để viết cho đúng, đẹp, kích thích hứng thú luyện viết chữ đẹp của học sinh.', E'Video có nội dung dạy viết các chữ viết thường cỡ nhỡ theo bảng chữ cái tiếng Việt kèm âm thanh hướng dẫn cách xác định độ cao, độ rộng cách chấm các điểm tọa độ từng chữ (điểm đặt bút, các điểm chuyển bút, điểm dừng bút).\nLưu ý: Kích cỡ dòng kẻ và chữ viết theo quy định chung của bộ mẫu chữ cái viết thường.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'1,2', E'Dùng cho lớp 1, 2', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'TH-TV-006', E'DM-TH-TV-006', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TIENG_VIET', 70, E'2', E'Video/ clip › Chủ đề 1. Tập viết', NULL, E'Video dạy viết các chữ viết hoa cỡ nhỡ theo bảng chữ cái tiếng Việt (2 kiểu: chữ đứng, chữ nghiêng)', E'Giúp học sinh thực hành quan sát, ghi nhớ mẫu các nét chữ viết để viết cho đúng, đẹp, kích thích hứng thú luyện viết chữ đẹp của học sinh.', E'Video có nội dung dạy viết các chữ viết hoa cỡ nhỡ theo bảng chữ cái tiếng Việt kèm âm thanh hướng dẫn cách xác định độ cao, độ rộng cách chấm các điểm tọa độ từng chữ (điểm đặt bút, các điểm chuyển bút, điểm dừng bút).\nLưu ý: Kích cỡ dòng kẻ và chữ theo quy định chung của bộ mẫu chữ cái viết hoa.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'1,2,3', E'Dùng cho lớp 1, 2, 3', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'TH-TV-007', E'DM-TH-TV-007', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TIENG_VIET', 80, E'1', E'Video/ clip › Chủ đề 2: Viết đoạn văn, bài văn', NULL, E'Video giới thiệu, tả đồ vật', E'Minh hoạ, giúp HS quan sát, tìm hiểu các đặc điểm của đồ vật phục vụ cho hoạt động nói, viết đoạn văn giới thiệu, miêu tả đồ vật.', E'Video/clip có nội dung về hình dáng, màu sắc, chất liệu, hoạt động của một số đồ vật quen thuộc trong đời sống, phù hợp với HS tiểu học.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'2,3', E'Dùng cho lớp 2, 3', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'TH-TV-008', E'DM-TH-TV-008', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TIENG_VIET', 90, E'2', E'Video/ clip › Chủ đề 2: Viết đoạn văn, bài văn', NULL, E'Video tả con vật, cây cối', E'Minh hoạ, giúp HS quan sát, tìm hiểu các đặc điểm của con vật, cây cối để nói, viết đoạn văn/ bài văn miêu tả.', E'- Video/clip có nội dung về hình dáng, hoạt động của một số con vật nuôi, con vật hoang dã (sống trong rừng, sống ở sông/ biển);\n- Video/clip có nội dung về đặc điểm của một số loài cây có trong tự nhiên (cây có hoa, cây bóng mát, cây ăn quả).', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'4', E'Dùng cho lớp 4', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'TH-TV-009', E'DM-TH-TV-009', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TIENG_VIET', 100, E'3', E'Video/ clip › Chủ đề 2: Viết đoạn văn, bài văn', NULL, E'Video tả người, tả cảnh', E'Minh hoạ, giúp HS quan sát, tìm hiểu các đặc điểm của người, của phong cảnh để viết bài văn miêu tả.', E'- Video/clip có nội dung về hình dáng, hoạt động của con người ở các độ tuổi, nghề nghiệp và công việc khác nhau;\n- Video/clip có nội dung về một số cảnh đẹp tiêu biểu ở các vùng, miền (biển, rừng núi, đồng bằng, miền Bắc, miền Trung, miền Nam).', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'5', E'Dùng cho lớp 5', E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'TH-TV-010', E'DM-TH-TV-010', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TOAN', 110, E'1', E'Thiết bị dùng chung › Hình học và đo lường', E'Hình học', E'Thiết bị vẽ bảng trong dạy học toán', E'GV sử dụng khi vẽ bảng trong dạy học Toán.', E'01 chiếc thước thẳng dài tối thiểu 500mm, độ chia nhỏ nhất là 1mm, được làm bằng nhựa/gỗ hoặc vật liệu khác có độ cứng tương đương, không cong vênh, màu sắc tươi sáng, an toàn với người sử dụng. Vạch kẻ trên thước thẳng, màu chữ và kẻ vạch trên thước tương phản với màu thước để dễ đọc số.', TRUE, TRUE, FALSE, E'CAI', E'Cái', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_DAY_HOC', E'PHYSICAL', E'SERIAL', NULL, E'TH-TOAN-001', E'DM-TH-TOAN-001', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TOAN', 120, E'1.1', E'Thiết bị theo các chủ đề › Dụng cụ', E'Số tự nhiên', E'Bộ thiết bị dạy chữ số và so sánh số', E'Giúp HS thực hành nhận biết số, đọc, viết, so sánh các số tự nhiên trong phạm vi từ 0 đến 100 (đối với lớp 1); từ 0 đến 1.000 (đối với lớp 2); từ 0 đến 100.000 (đối với lớp 3).', E'Bộ thiết bị dạy chữ số và so sánh số gồm:\na) Các thẻ chữ số từ 0 đến 9. Mỗi chữ số có 4 thẻ chữ, in chữ màu và gắn được lên bảng; kích thước mỗi thẻ (30x50)mm;\nb) 20 que tính dài 100mm, tiết diện ngang 3mm;\nc) 10 thẻ in hình bó chục que tính gồm 10 que tính gắn liền nhau, mỗi que tính có kích thước (100x3)mm;\nd) Thẻ dấu so sánh (lớn hơn, bé hơn, bằng); mỗi dấu 02 thẻ, in chữ màu và gắn được lên bảng; kích thước mỗi thẻ (30x50)mm;\nđ) 10 thanh chục khối lập phương (thanh chục khối lập phương là một tấm nhựa hình chữ nhật kích thước (15x150)mm, vẽ mô hình 3D của 10 khối lập phương được xếp thành một cột);\ne) 10 bảng trăm (bảng trăm là một tấm nhựa hình vuông kích thước (150x150)mm, vẽ mô hình 3D của 100 khối lập phương được xếp thành 10 hàng, mỗi hàng gồm 10 hình lập phương);\ng) 10 thẻ khối 1.000 (thẻ khối 1.000 là một tấm nhựa hình vuông vẽ mô hình 3D của 1000 khối lập phương, mỗi khối lập phương có kích thước (15x15x15)mm), tạo thành một mô hình 3D của khối lập phương có kích thước (150x150x150)mm;\nh) 10 thanh 10.000 (thanh 10.000 là một tấm nhựa hình chữ nhật kích thước (15x150)mm vẽ mô hình 3D của 10 thẻ 1.000 chồng khít lên nhau);\ni) 01 thẻ ghi số 100.000 hình chữ nhật có kích thước (60x90)mm.\nVật liệu: Tất cả các thiết bị trên được làm bằng nhựa (hoặc vật liệu có độ cứng tương đương), không cong vênh, chịu được nước, có màu tươi sáng, an toàn trong sử dụng.', FALSE, TRUE, FALSE, E'BO', E'Bộ', E'01/HS', 1, E'PER_STUDENT', NULL, E'1,2,3', E'Dùng cho lớp 1, 2, 3; Dùng cho lớp 1; Dùng cho lớp 2; Dùng cho lớp 3,4', E'DO_DUNG_DAY_HOC', E'PHYSICAL', E'SERIAL', NULL, E'TH-TOAN-002', E'DM-TH-TOAN-002', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TOAN', 130, E'1.2', E'Thiết bị theo các chủ đề › Dụng cụ', E'SỐ VÀ PHÉP TÍNH', E'Bộ thiết bị dạy phép tính', E'HS thực hành cộng, trừ trong phạm vi 10, cộng trừ (không nhớ) trong phạm vi 100 đối với lớp 1;\nGiúp HS thực hành cộng, trừ (có nhớ) trong phạm vi 20, cộng, trừ (không nhớ, có nhớ) trong phạm vi 1.000;\nPhép nhân, phép chia (bảng nhân 2,5; bảng chia 2,5)\nGiúp HS thực hành cộng, trừ (không và có nhớ) trong phạm vi 10.000/100.000, phép nhân, phép chia trong phạm vi 10.000/100.000.', E'Bộ thiết bị dạy phép tính gồm:\na) Thẻ dấu phép tính (cộng, trừ, nhân, chia); mỗi dấu 02 thẻ, in chữ màu và gắn được lên bảng; kích thước mỗi thẻ (30x50)mm;\nb) 20 que tính dài 100mm, tiết diện ngang 3mm (như đã mô tả trong 1.1.b);\nc) 10 thẻ in hình bó chục que tính - gồm 10 que tính gắn liền nhau, mỗi que tính có kích thước (100x3)mm (như đã mô tả trong 1.1.c);\nd) 10 bảng trăm (bảng trăm là một tấm nhựa hình vuông kích thước (150x150)mm, vẽ mô hình 3D của 100 khối lập phương được xếp thành 10 hàng, mỗi hàng gồm 10 hình lập phương (như đã mô tả trong 1.1.e);\ne) 10 thẻ mỗi thẻ 2 chấm tròn, 10 thẻ mỗi thẻ 5 chấm tròn, đường kính mỗi chấm tròn trong thẻ 15mm.\nVật liệu: Tất cả các thiết bị được làm bằng nhựa (hoặc vật liệu có độ cứng tương đương), không cong vênh, chịu được nước, có màu tươi sáng, an toàn trong sử dụng.', FALSE, FALSE, FALSE, E'BO', E'Bộ', E'01/HS', 1, E'PER_STUDENT', NULL, E'1,2,3', E'Dùng cho lớp 1, 2, 3; Dùng cho lớp 1; Dùng cho lớp 2, 3', E'DO_DUNG_DAY_HOC', E'PHYSICAL', E'SERIAL', NULL, E'TH-TOAN-003', E'DM-TH-TOAN-003', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TOAN', 140, E'2.1', E'Thiết bị theo các chủ đề › Dụng cụ', E'Hình học', E'Bộ thiết bị vẽ bảng trong dạy học hình học', E'GV sử dụng khi vẽ bảng trong dạy học hình học.', E'Bộ thiết bị vẽ bảng gồm:\n- 01 ê ke có kích thước các cạnh (300x400x500)mm;\n- 01 chiếc compa dài 400mm với đầu được thiết kế thuận lợi khi vẽ trên bảng bằng phấn, bút dạ, một đầu thuận lợi cho việc cố định trên mặt bảng;\n- 01 thước đo góc đường kính 300mm, có hai đường chia độ, khuyết ở giữa.\nVật liệu: Tất cả các thiết bị được làm bằng nhựa/gỗ hoặc vật liệu có độ cứng tương đương, không cong vênh, màu sắc tươi sáng, an toàn với người sử dụng.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'3,4,5', E'Dùng cho lớp 3, 4, 5', E'THIET_BI_DAY_HOC', E'PHYSICAL', E'SERIAL', NULL, E'TH-TOAN-004', E'DM-TH-TOAN-004', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TOAN', 150, E'2.2', E'Thiết bị theo các chủ đề › Dụng cụ', E'Khối lượng', E'Bộ thiết bị dạy khối lượng', E'Giúp HS thực hành cân.', E'Bộ thiết bị dạy khối lượng gồm:\n- 01 cân đĩa loại 5kg;\n- 01 hộp quả cân loại: 10g, 20g, 50g, 100g, 200g, 500g, 1kg; 2kg (mỗi loại 2 quả).', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'04/lớp', 4, E'PER_CLASS', NULL, E'2,3', E'Dùng cho lớp 2, 3', E'DO_DUNG_DAY_HOC', E'PHYSICAL', E'SERIAL', NULL, E'TH-TOAN-005', E'DM-TH-TOAN-005', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TOAN', 160, E'2.3', E'Thiết bị theo các chủ đề › Dụng cụ', E'Dung tích', E'Bộ thiết bị dạy dung tích', E'Giúp HS thực hành đo dung tích.', E'Bộ thiết bị dạy dung tích gồm:\n- 01 chai 1 lít, có 10 vạch chia ghi các số 100; 200; 300; …; 1.000;\n- 01 ca 1 lít, có 10 vạch chia ghi các số 100; 200; 300; …; 1.000.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'04/lớp', 4, E'PER_CLASS', NULL, E'2,3', E'Dùng cho lớp 2, 3', E'DO_DUNG_DAY_HOC', E'PHYSICAL', E'SERIAL', NULL, E'TH-TOAN-006', E'DM-TH-TOAN-006', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TOAN', 170, E'2.4', E'Thiết bị theo các chủ đề › Dụng cụ', E'Diện tích', E'Thiết bị dạy diện tích', E'Giúp HS thực hành đo diện tích.', E'Thiết bị dạy diện tích là tấm phẳng trong suốt, kẻ ô vuông một chiều 10 ô, một chiều 20 ô. Ô vuông có kích thước (10x10)mm.', TRUE, TRUE, FALSE, E'TAM', E'Tấm', E'06/lớp', 6, E'PER_CLASS', NULL, E'3', E'Dùng cho lớp 3', E'THIET_BI_DAY_HOC', E'PHYSICAL', E'SERIAL', NULL, E'TH-TOAN-007', E'DM-TH-TOAN-007', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TOAN', 180, E'3.1', E'Thiết bị theo các chủ đề › Dụng cụ', E'Xác suất', E'Bộ thiết bị dạy học yếu tố xác suất', E'Giúp HS khám phá, hình thành, thực hành, luyện tập về khả năng xảy ra của một sự kiện (hay hiện tượng).', E'Bộ thiết bị dạy học yếu tố xác suất gồm:\n- 01 quân xúc xắc có độ dài cạnh là 20mm; có 6 mặt, số chấm xuất hiện ở mỗi mặt là một trong các số 1; 2; 3; 4; 5; 6 (mặt 1 chấm; mặt 2 chấm; … ; mặt 6 chấm);\n- 01 hộp nhựa trong để tung quân xúc xắc (Kích thước phù hợp với quân xúc xắc);\n- 02 đồng xu gồm một đồng xu to có đường kính 25mm và một đồng xu nhỏ có đường kính 20mm; độ dày 1mm; làm bằng hợp kim (nhôm, đồng). Trên mỗi đồng xu, một mặt khắc nổi chữ N, mặt kia khắc nổi chữ S;\n- 01 hộp bóng có 3 quả, trong đó có 1 quả bóng xanh, 1 quả bóng đỏ và 1 quả bóng vàng, các quả bóng có kích thước và trọng lượng như nhau với đường kính 35mm (giống quả bóng bàn).', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'06/lớp', 6, E'PER_CLASS', NULL, E'3,4,5', E'Dùng cho lớp 3, 4, 5', E'DO_DUNG_DAY_HOC', E'PHYSICAL', E'SERIAL', NULL, E'TH-TOAN-008', E'DM-TH-TOAN-008', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TOAN', 190, E'1.1', E'Thiết bị theo các chủ đề › Mô hình', E'Phân số', E'Bộ thiết bị hình học dạy phân số', E'GV sử dụng khi dạy học về phân số.', E'Bộ thiết bị hình học dạy phân số gồm:\n- 09 hình tròn đường kính 160mm, độ dày của vật liệu tối thiểu là 1,5mm màu sáng (trong đó có 5 hình được chia thành 4 phần đều nhau qua tâm bằng nét kẻ rộng 1mm; sơn màu đỏ 1/4 hình; 1 hình được chia thành 4 phần đều nhau qua tâm bằng nét kẻ rộng 1mm, đường viền theo chu vi và đường kẻ chia (không tiếp xúc với phần sơn) là nét kẻ đứt rộng 1mm, sơn đỏ 1/4; 1 hình được chia thành 4 phần đều nhau qua tâm bằng nét kẻ rộng 1mm toàn bộ hình tròn sơn màu đỏ; 1 hình được chia thành 2 phần đều nhau qua tâm bằng nét kẻ rộng 1mm; sơn đỏ 1/2 hình; 1 hình được chia thành 6 phần đều nhau qua tâm bằng nét kẻ rộng 1mm, sơn đỏ 5/6 hình tròn);\n- 02 hình tròn đường kính 160mm, độ dày của vật liệu tối thiểu là 1,5mm, chuyển động quay tương đối với nhau thông qua trục nối tâm có vòng đệm ở giữa; một hình trong suốt, một hình màu tối (mỗi hình: được chia thành 8 phần đều nhau qua tâm bằng nét kẻ, sơn màu đỏ 1/2 hình tròn. Các đường bao, đường nối tâm, có chiều rộng 1mm);\n- 04 hình vuông có kích thước (160x160)mm, màu trắng (trong đó có 3 hình chia thành 4 hình vuông nhỏ đều nhau qua tâm, bằng nét kẻ rộng 1mm, 1/4 hình có màu xanh cô ban và 1 hình chia thành 4 hình vuông nhỏ đều nhau qua tâm, bằng nét kẻ rộng 1mm, riêng phần không màu là nét kẻ đứt, 3/4 hình có màu xanh cô ban), độ dày của vật liệu tối thiểu là 1,5 mm.\n(Ghi chú: Các hình có thể sử dụng từ tính để giáo viên đính lên bảng từ)', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, E'4,5', E'Dùng cho lớp 4,5', E'MO_HINH_MAU_VAT', E'PHYSICAL', E'SERIAL', NULL, E'TH-TOAN-009', E'DM-TH-TOAN-009', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TOAN', 200, E'1.2', E'Thiết bị theo các chủ đề › Mô hình', E'Phân số', E'Bộ thiết bị hình học thực hành phân số', E'Giúp HS khám phá, hình thành, thực hành, luyện tập về phân số.', E'Bộ thiết bị hình học dạy học phân số gồm:\n- 09 hình tròn đường kính Φ 40mm, độ dày của vật liệu tối thiểu là 1,2mm màu sáng (trong đó có 5 hình được chia thành 4 phần đều nhau qua tâm bằng nét kẻ rộng 1mm; sơn màu đỏ 1/4 hình; 1 hình được chia thành 4 phần đều nhau qua tâm bằng nét kẻ rộng 1mm, đường viền theo chu vi và đường kẻ chia (không tiếp xúc với phần sơn) là nét kẻ đứt rộng 1mm, sơn đỏ 1/4; 1 hình được chia thành 4 phần đều nhau qua tâm bằng nét kẻ rộng 1mm toàn bộ hình tròn sơn màu đỏ; 1 hình được chia thành 2 phần đều nhau qua tâm bằng nét kẻ rộng 1mm; sơn đỏ 1/2 hình; 1 hình được chia thành 6 phần đều nhau qua tâm bằng nét kẻ rộng 1mm, sơn đỏ 5/6 hình tròn;\n- 04 hình vuông có kích thước (40x40)mm, màu trắng (trong đó có 3 hình chia thành 4 hình vuông nhỏ đều nhau qua tâm, bằng nét kẻ rộng 1mm, 1/4 hình có màu xanh cô ban và 1 hình chia thành 4 hình vuông nhỏ đều nhau qua tâm, bằng nét kẻ rộng 1mm, riêng phần không màu là nét kẻ đứt, 3/4 hình có màu xanh cô ban), độ dày của vật liệu tối thiểu là 1,2mm.', FALSE, TRUE, FALSE, E'BO', E'Bộ', E'01/HS', 1, E'PER_STUDENT', NULL, E'4,5', E'Dùng cho lớp 4, 5', E'MO_HINH_MAU_VAT', E'PHYSICAL', E'SERIAL', NULL, E'TH-TOAN-010', E'DM-TH-TOAN-010', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TOAN', 210, E'2.1', E'Thiết bị theo các chủ đề › Mô hình', E'Hình phẳng và hình khối', E'Bộ thiết bị dạy hình phẳng và hình khối.', E'- Giúp GV dạy hình phẳng và hình khối.\n- Giúp HS thực hành nhận dạng hình phẳng và hình khối, lắp ghép xếp hình.', E'Bộ thiết bị dạy hình phẳng và hình khối gồm:\na) Các hình phẳng gồm: 6 hình tam giác đều cạnh 40mm; 4 hình tam giác vuông cân có cạnh góc vuông 50mm; 2 hình tam giác vuông có 2 cạnh góc vuông 40mm và 60mm; 10 hình vuông kích thước (40x40)mm; 8 hình tròn đường kính 40mm, 2 hình chữ nhật kích thước (40x80)mm. Các hình có độ dày của vật liệu tối thiểu là 2mm;\nb) 4 hình tứ giác khác nhau (cạnh ngắn nhất 30mm, cạnh dài nhất 70mm, độ dày của vật liệu tối thiểu là 2mm);\nc1) - 02 hình thang bằng nhau, kích thước đáy lớn 280mm, đáy nhỏ 200mm, chiều cao 150mm, độ dày của vật liệu tối thiểu là 2mm, màu đỏ, đường cao màu trắng (trong đó có 1 hình giữ nguyên; 1 hình cắt ra 2 phần ghép lại được hình tam giác);\n- 02 hình tam giác bằng nhau, kích thước cạnh đáy 250mm, cạnh xiên 220mm, cao 150mm, độ dày của vật liệu tối thiểu là 2 mm, màu xanh côban (trong đó có 1 hình tam giác giữ nguyên, có đường cao màu đen; 1 hình cắt thành 2 tam giác theo đường cao để ghép với hình trên được hình chữ nhật);\nc2) - 02 hình thang bằng nhau, kích thước 2 đáy 80mm và 50mm, chiều cao 40mm, độ dày của vật liệu tối thiểu là 1,2 mm, màu đỏ, kẻ đường cao (trong đó có 1 hình thang nguyên; 1 hình thang cắt ra 2 phần ghép lại được hình tam giác);\n- 02 hình tam giác bằng nhau, kích thước đáy 80mm, cao 40mm, 1 góc 60°, độ dày của vật liệu tối thiểu là 1,2mm, màu xanh côban (trong đó có 1 hình tam giác nguyên, có kẻ đường cao; 1 hình tam giác cắt theo đường cao thành 2 tam giác để ghép với hình trên được hình chữ nhật (80x40)mm);\nd1) 01 hình bình hành màu xanh cô ban có kích thước cạnh dài 240mm, đường cao 160mm, độ dày của vật liệu tối thiểu là 1,5mm, góc nhọn 60°;\nd2) 01 hình bình hành có cạnh dài 80mm, cao 50mm, góc nhọn 60°, độ dày của vật liệu tối thiểu là 1,2mm;\ne1) 02 hình thoi màu đỏ có kích thước 2 đường chéo là 300mm và 160mm, độ dày của vật liệu tối thiểu là 1,5mm (1 hình giữ nguyên, 1 hình cắt làm 3 hình tam giác theo đường chéo dài và nửa đường chéo ngắn);\ne2) 02 hình thoi có hai đường chéo 80mm và 60mm, độ dày của vật liệu tối thiểu là 1,2mm (trong đó 1 hình giữ nguyên và 1 hình cắt làm 3 hình tam giác theo đường chéo dài và nửa đường chéo ngắn);\ng1) 04 khối hộp chữ nhật kích thước (40x40x60)mm;\ng2) 04 khối lập phương kích thước (40x40x40)mm; 04 khối trụ đường kính 40mm (trong đó, 2 cái cao 40mm, 2 cái cao 60mm); 4 khối cầu đường kính 40mm; 4 khối cầu đường kính 60mm;\ng3) - 01 hình hộp chữ nhật kích thước (200x160x100)mm, 4 mặt xung quanh màu trắng, 2 đáy màu đỏ, độ dày của vật liệu tối thiểu là 2mm, các mặt liên kết với nhau bằng màng PET 0,05mm, có thể mở ra thành hình khai triển của hình hộp chữ nhật (gắn được trên bảng từ);\n- 01 hình hộp chữ nhật biểu diễn cách tính thể tích, kích thước trong hộp (200x160x100)mm, trong suốt, độ dày của vật liệu tối thiểu là 2mm. Bên trong chứa 1 tấm đáy (200x160x10)mm và 1 cột (10x10x90)mm, sơn ô vuông (10x10)mm bằng hai màu trắng, đỏ;\n- 01 hình lập phương cạnh 200mm, 4 mặt xung quanh màu trắng, 2 mặt đáy màu đỏ, độ dày của vật liệu tối thiểu là 2mm, các mặt liên kết với nhau bằng màng PET 0,05mm, có thể mở ra thành hình khai triển của hình lập phương (gắn được trên bảng từ);\n- 01 hình lập phương cạnh 100mm biểu diễn thể tích 1dm3, trong suốt, bên trong chứa 1 tấm đáy có kích thước bằng (100x100x10)mm và 1 cột (10x10x90)mm, ô vuông (10x10)mm có hai màu xanh, trắng;\n- 01 hình trụ làm bằng vật liệu trong suốt, độ dày tối thiểu là 2mm, đáy có đường kính 100mm, chiều cao 150mm;\n- 01 hình cầu làm bằng vật liệu màu đỏ trong suốt, độ dày tối thiểu là 3mm, đường kính 200mm; Giá đỡ có đường kính 90mm, chiều cao 20mm, độ dày tối thiểu là 2mm.\nVật liệu: Tất cả các thiết bị được làm bằng nhựa, gỗ (hoặc vật liệu có độ cứng tương đương), có màu sắc tươi sáng, an toàn trong sử dụng.', FALSE, FALSE, FALSE, E'BO', E'Bộ', E'01/HS', 1, E'PER_STUDENT', NULL, E'1,2,3', E'Dùng cho lớp 1, 2, 3; Dùng cho lớp 2, 3; Dùng cho lớp 5; Dùng cho lớp 4', E'MO_HINH_MAU_VAT', E'PHYSICAL', E'SERIAL', NULL, E'TH-TOAN-011', E'DM-TH-TOAN-011', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TOAN', 220, E'2.2', E'Thiết bị theo các chủ đề › Mô hình', E'Mét vuông', E'Bộ thiết bị dạy học dạy đơn vị đo diện tích mét vuông', E'GV sử dụng khi dạy về diện tích.', E'01 bảng kích thước (1.250x1.030)mm, được kẻ thành các ô có kích thước (100x100)mm.', TRUE, FALSE, FALSE, E'BANG', E'Bảng', E'01/GV', 1, E'PER_TEACHER', NULL, E'4', E'Dùng cho lớp 4', E'MO_HINH_MAU_VAT', E'PHYSICAL', E'SERIAL', NULL, E'TH-TOAN-012', E'DM-TH-TOAN-012', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TOAN', 230, E'2.3', E'Thiết bị theo các chủ đề › Mô hình', E'Thời gian', E'Thiết bị trong dạy học về thời gian', E'Giúp HS thực hành xem đồng hồ.', E'Mô hình đồng hồ đường kính 300mm có kim giờ, kim phút và có thể quay đồng bộ với nhau, trên mặt đồng hồ có 60 vạch để chỉ 60 phút.', TRUE, FALSE, FALSE, E'CHIEC', E'Chiếc', E'01/lớp', 1, E'PER_CLASS', NULL, E'1,2,3', E'Dùng cho lớp 1, 2, 3', E'MO_HINH_MAU_VAT', E'PHYSICAL', E'SERIAL', NULL, E'TH-TOAN-013', E'DM-TH-TOAN-013', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TOAN', 240, E'1', E'Thiết bị theo các chủ đề › Phần mềm', E'Hình học và đo lường', E'Phần mềm toán học', E'Phần mềm toán học hỗ trợ GV giúp HS thực hành, luyện tập các yếu tố hình học.', E'Phần mềm toán học đảm bảo hỗ trợ GV vẽ hình trong dạy học các yếu tố hình học;\nPhải sử dụng phần mềm không vi phạm bản quyền.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'TH-TOAN-014', E'DM-TH-TOAN-014', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TOAN', 250, E'2', E'Thiết bị theo các chủ đề › Phần mềm', E'Thống kê và xác suất', E'Phần mềm toán học', E'Phần mềm toán học hỗ trợ GV giúp HS thực hành, luyện tập các yếu tố Thống kê và xác suất.', E'Phần mềm toán học đảm bảo hỗ trợ GV vẽ bảng, biểu đồ; mô tả thí nghiệm ngẫu nhiên trong dạy học các yếu tố Thống kê và xác suất; Phải sử dụng phần mềm không vi phạm bản quyền.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'TH-TOAN-014', E'DM-TH-TOAN-015', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TIENG_ANH', 260, E'1', E'Thiết bị dạy học ngoại ngữ thông dụng (lựa chọn 1)', NULL, E'Đài đĩa CD', E'Phát các học liệu âm thanh.', E'- Phát các loại đĩa CD có các định dạng phổ thông;\n- Có cổng USB và/hoặc thẻ nhớ;\n- Có chức năng nhớ, tua tiến, tua lùi, tạm dừng;\n- Đài AM, FM;\n- Nguồn điện: AC 110-220V/50 Hz, sử dụng được pin.', TRUE, FALSE, FALSE, E'CHIEC', E'Chiếc', E'01', 1, E'PER_SCHOOL', NULL, NULL, E'Có thể sử dụng thiết bị dùng chung', E'MAY_MOC_THIET_BI', E'PHYSICAL', E'SERIAL', NULL, E'TH-NN-001', E'DM-TH-NN-001', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TIENG_ANH', 270, E'2', E'Thiết bị dạy học ngoại ngữ thông dụng (lựa chọn 1)', NULL, E'Đầu đĩa', E'Phát học liệu hình ảnh và âm thanh cho các hoạt động nghe và nói.', E'- Loại thông dụng;\n- Đọc đĩa DVD, VCD/CD, CD - RW và các chuẩn thông dụng khác;\n- Có cổng kết nối USB, thẻ nhớ;\n- Tín hiệu ra dưới dạng AV, HDMI;\n- Chức năng tua tiến, tua lùi, tạm dừng;\n- Điều khiển từ xa;\n- Nguồn điện: 90V - 240V/50 Hz.', TRUE, FALSE, FALSE, E'CHIEC', E'Chiếc', E'01', 1, E'PER_SCHOOL', NULL, NULL, E'Có thể sử dụng thiết bị dùng chung', E'MAY_MOC_THIET_BI', E'PHYSICAL', E'SERIAL', NULL, E'TH-NN-002', E'DM-TH-NN-002', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TIENG_ANH', 280, E'3', E'Thiết bị dạy học ngoại ngữ thông dụng (lựa chọn 1)', NULL, E'Máy chiếu (hoặc Màn hình hiển thị)', E'Kết nối với máy tính và các thiết bị khác để phát âm thanh, hình ảnh.', E'Máy chiếu:\nLoại thông dụng.\n- Có đủ cổng kết nối phù hợp;\n- Cường độ sáng tối thiểu 3.500 Ansilumens;\n- Độ phân giải tối thiểu XGA;\n- Kích cỡ khi chiếu lên màn hình tối thiểu 100 inch;\n- Điều khiển từ xa;\n- Kèm theo màn chiếu và thiết bị điều khiển (nếu có).\nMàn hình hiển thị:\nLoại thông dụng, màn hình tối thiểu 50 inch, Full HD\n- Có đủ cổng kết nối phù hợp;\n- Có ngôn ngữ hiển thị Tiếng Việt;\n- Điều khiển từ xa;\n- Nguồn điện: AC 90-220V/50Hz.', TRUE, FALSE, FALSE, E'CHIEC', E'Chiếc', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'MAY_MOC_THIET_BI', E'PHYSICAL', E'SERIAL', NULL, E'TH-NN-003', E'DM-TH-NN-003', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TIENG_ANH', 290, E'4', E'Thiết bị dạy học ngoại ngữ thông dụng (lựa chọn 1)', NULL, E'Bộ máy vi tính để bàn/hoặc máy tính xách tay', E'Kết nối với các thiết bị ngoại vi để trình chiếu bài giảng.', E'- Loại thông dụng có cấu hình tối thiểu cài đặt được các hệ điều hành và các phần mềm dạy học ngoại ngữ;\n- Màn hình tối thiểu: 17 inch (máy tính để bàn), 14 inch (máy tính xách tay);\n- Có các cổng kết nối tối thiểu: VGA, HDMI, USB, LAN, Wifi và Bluetooth.', TRUE, FALSE, FALSE, E'CHIEC', E'Chiếc', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'THIET_BI_CNTT', E'PHYSICAL', E'SERIAL', NULL, E'TH-NN-004', E'DM-TH-NN-004', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TIENG_ANH', 300, E'5', E'Thiết bị dạy học ngoại ngữ thông dụng (lựa chọn 1)', NULL, E'Thiết bị âm thanh đa năng di động', E'Phát các học liệu âm thanh và trợ âm cho giáo viên.', E'- Tích hợp được nhiều tính năng âm ly, loa, micro, đọc các định dạng DVD, CD, SD, USB trên thiết bị;\n- Kết nối line-in, audio in, bluetooth với nguồn phát âm thanh;\n- Công suất phù hợp với lớp học;\n- Kèm theo micro;\n- Nguồn điện: AC 220V/50Hz; DC, có ắc quy/pin sạc.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01', 1, E'PER_SCHOOL', NULL, NULL, NULL, E'MAY_MOC_THIET_BI', E'PHYSICAL', E'SERIAL', NULL, E'TH-NN-005', E'DM-TH-NN-005', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TIENG_ANH', 310, E'6', E'Thiết bị dạy học ngoại ngữ thông dụng (lựa chọn 1)', NULL, E'Bộ học liệu bằng tranh', NULL, E'Bộ tranh có nội dung theo các chủ điểm/chủ đề trong chương trình môn Ngoại ngữ cấp Tiểu học theo Chương trình giáo dục phổ thông 2018, kích thước (148x210)mm, in offset 4 màu trên giấy couche định lượng 200g/m2, cán láng OPP mờ (hoặc in màu trên nhựa).', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'04 đến 06/GV', 4, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_DAY_HOC', E'PHYSICAL', E'SERIAL', NULL, E'TH-NN-006', E'DM-TH-NN-006', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TIENG_ANH', 320, E'7', E'Thiết bị dạy học ngoại ngữ thông dụng (lựa chọn 1)', NULL, E'Bộ học liệu điện tử', E'Hỗ trợ giáo viên xây dựng kế hoạch dạy học, kế hoạch bài dạy (điện tử), bài giảng (điện tử), học liệu (điện tử), bài tập, bài kiểm tra đánh giá.', E'Bộ học liệu điện tử được xây dựng theo chương trình môn Ngoại ngữ cấp Tiểu học theo Chương trình giáo dục phổ thông 2018, không vi phạm các quy định về bản quyền, pháp luật, chủ quyền, văn hóa, dân tộc, giới, các đối tượng dễ tổn thương, có hệ thống học liệu điện tử (bài nghe, video, hình ảnh, bài giảng điện tử để dạy luyện nghe/nói cho học sinh, hệ thống câu hỏi, đề kiểm tra) đi kèm và được tổ chức, quản lý thành hệ thống thư viện điện tử, thuận tiện cho tra cứu và sử dụng. Bộ học liệu sử dụng được trên máy tính trong môi trường không có kết nối internet. Đảm bảo các chức năng:\n- Chức năng hỗ trợ soạn kế hoạch bài dạy điện tử;\n- Chức năng chuẩn bị bài giảng điện tử;\n- Chức năng chèn các học liệu điện tử (hình ảnh, video, âm thanh) vào giáo án điện tử;\n- Chức năng tạo câu hỏi, bài tập;\n- Chức năng kiểm tra đánh giá.\nBộ học liệu điện tử gồm các bài nghe, video, hình ảnh, bài giảng điện tử để dạy cho học sinh. Các nội dung phải phù hợp với chương trình.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/GV', 1, E'PER_TEACHER', NULL, NULL, NULL, E'THIET_BI_CNTT', E'DIGITAL', E'SERIAL', NULL, E'TH-NN-007', E'DM-TH-NN-007', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TIENG_ANH', 330, E'1', E'Hệ thống thiết bị dạy học ngoại ngữ chuyên dụng', NULL, E'Máy chiếu đa năng hoặc Màn hình hiển thị', E'Kết nối với máy tính và các thiết bị khác để phát âm thanh hình ảnh.', E'Máy chiếu:\nLoại thông dụng.\n- Có đủ cổng kết nối phù hợp;\n- Cường độ sáng tối thiểu 3.500 Ansilumens;\n- Độ phân giải tối thiểu XGA;\n- Kích cỡ khi chiếu lên màn hình tối thiểu 100 inch;\n- Điều khiển từ xa;\n- Kèm theo màn chiếu và thiết bị điều khiển (nếu có).\nMàn hình hiển thị:\nLoại thông dụng, màn hình tối thiểu 50 inch, Full HD\n- Có đủ cổng kết nối phù hợp;\n- Có ngôn ngữ hiển thị Tiếng Việt;\n- Điều khiển từ xa;\n- Nguồn điện: AC 90-220V/50Hz.', TRUE, FALSE, TRUE, E'CHIEC', E'Chiếc', E'01', 1, E'PER_ROOM', NULL, NULL, NULL, E'MAY_MOC_THIET_BI', E'PHYSICAL', E'SERIAL', NULL, E'TH-NN-008', E'DM-TH-NN-008', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
