(E'TH', E'KHOA_HOC', 1790, E'2.6', E'Dụng cụ', E'Nấm', E'Kính lúp', E'HS thực hành, quan sát nấm.', E'Loại thông dụng (loại kính lúp cầm tay), độ phóng đại 6x.', TRUE, TRUE, FALSE, E'CHIEC', E'Chiếc', E'05/PHBM', 5, E'PER_ROOM', NULL, E'4', E'Dùng cho lớp 4', E'THIET_BI_THI_NGHIEM', E'PHYSICAL', E'SERIAL', NULL, E'TH-KH-016', E'DM-TH-KH-016', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'KHOA_HOC', 1800, E'1', E'Thiết bị phòng học bộ môn', NULL, E'Máy chiếu (hoặc Màn hình hiển thị)', E'Trình chiếu', E'Máy chiếu:\n- Loại thông dụng.\n- Có đủ cổng kết nối phù hợp;\n- Cường độ sáng tối thiểu 3.500 Ansilumens;\n- Độ phân giải tối thiểu XGA;\n- Kích cỡ khi chiếu lên màn hình tối thiểu 100 inch;\n- Điều khiển từ xa;\n- Kèm theo màn chiếu và thiết bị điều khiển (nếu có).\nMàn hình hiển thị:\n- Loại thông dụng, màn hình tối thiểu 50 inch, Full HD;\n- Có đủ cổng kết nối phù hợp;\n- Có ngôn ngữ hiển thị Tiếng Việt;\n- Điều khiển từ xa;\n- Nguồn điện: AC 90-220V/50Hz.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01/PHBM', 1, E'PER_ROOM', NULL, NULL, NULL, E'MAY_MOC_THIET_BI', E'PHYSICAL', E'SERIAL', NULL, E'TH-KH-017', E'DM-TH-KH-017', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TIN_HOC', 1810, E'1', E'Phòng thực hành tin học', NULL, E'Máy chủ', E'Quản lý, kết nối mạng cho các máy của HS và lưu trữ các phần mềm, học liệu phục vụ dạy và học.', E'- Sử dụng một máy tính PC có cấu hình RAM, ổ cứng có dung lượng lớn hơn máy dùng cho HS để cài đặt làm máy chủ, cấu hình đảm bảo:\n+ Lưu trữ bài thực hành của HS và các phần mềm, học liệu phục vụ dạy và học;\n+ Quản lý, kết nối tất cả máy tính và các thiết bị ngoại vi trong phòng máy;\n- Cài đặt được hệ điều hành và các phần mềm ứng dụng phục vụ quản lý và tổ chức dạy học không vi phạm bản quyền;\n- Kết nối được Internet.', TRUE, FALSE, FALSE, E'BO', E'Bộ', E'01', 1, E'PER_ROOM', NULL, NULL, NULL, E'THIET_BI_CNTT', E'PHYSICAL', E'SERIAL', NULL, E'TH-TIN-001', E'DM-TH-TIN-001', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
(E'TH', E'TIN_HOC', 1820, E'2', E'Phòng thực hành tin học', NULL, E'Máy tính để bàn hoặc máy tính xách tay', E'Dạy, học và thực hành', E'- Cấu hình đảm bảo:\n+ Cài đặt được các phần mềm dạy học của các môn học trong nhà trường;\n+ Kết nối được mạng LAN và Internet.\n- Bao gồm: bàn phím, chuột, màn hình, tai nghe, Micro, Webcam (độ phân giải tối thiểu: 480p/30fps);\n- Cài đặt được hệ điều hành và phần mềm dạy học không vi phạm bản quyền.', FALSE, TRUE, FALSE, E'BO', E'Bộ', E'01/3HS', 1, E'PER_STUDENT', 3, NULL, E'1 bộ máy tính /3HS là tối thiểu, những nơi có điều kiện có thể trang bị 1 bộ máy tính/2 (hoặc 1)HS', E'THIET_BI_CNTT', E'PHYSICAL', E'SERIAL', NULL, E'TH-TIN-002', E'DM-TH-TIN-002', E'TT 37/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (02/VBHN-BGDĐT)'),
