(E'THCS', E'AM_NHAC', 6410, E'1', E'Nhạc cụ thể hiện tiết tấu', NULL, E'Trống nhỏ', E'HS luyện tập tiết tấu', E'Theo mẫu của loại trống thông dụng, gồm trống và một dùi gõ. Trống có đường kính 180mm, chiều cao 75mm.', TRUE, TRUE, FALSE, E'BO', E'Bộ', E'05/GV', 5, E'PER_TEACHER', NULL, E'6,7', E'Dùng cho lớp 6, 7', E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THCS-AN-001', E'DM-THCS-AN-001', E'TT 38/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (03/VBHN-BGDĐT)'),
(E'THCS', E'AM_NHAC', 6420, E'2', E'Nhạc cụ thể hiện tiết tấu', NULL, E'Song loan', E'HS luyện tập tiết tấu', E'Theo mẫu của nhạc cụ dân tộc, gồm hai mảnh gỗ hình tròn (có kích thước khác nhau) được nối với nhau bằng một thanh mỏng.', TRUE, TRUE, FALSE, E'CAI', E'Cái', E'10/GV', 10, E'PER_TEACHER', NULL, E'6,7,8,9', E'Dùng cho lớp 6, 7, 8, 9', E'DUNG_CU', E'PHYSICAL', E'SERIAL', NULL, E'THCS-AN-002', E'DM-THCS-AN-002', E'TT 38/2021/TT-BGDĐT, sửa đổi bởi TT 26/2023/TT-BGDĐT (03/VBHN-BGDĐT)'),
